  'Duyệt giai đoạn "{name}"?': { en: 'Approve phase "{name}"?', zh: '批准阶段“{name}”？', ja: 'フェーズ「{name}」を承認しますか？', ko: '"{name}" 단계를 승인할까요?', es: '¿Aprobar la fase «{name}»?', fr: 'Approuver la phase « {name} » ?', de: 'Phase „{name}“ genehmigen?', th: 'อนุมัติระยะ "{name}" หรือไม่?', id: 'Setujui fase "{name}"?' },
  'Dự án sẽ chuyển sang giai đoạn tiếp theo ngay sau khi duyệt.': { en: 'The project moves to the next phase right after approval.', zh: '批准后项目将立即进入下一阶段。', ja: '承認後すぐに次のフェーズへ進みます。', ko: '승인 즉시 프로젝트가 다음 단계로 넘어갑니다.', es: 'El proyecto pasará a la siguiente fase justo después de aprobarla.', fr: 'Le projet passe à la phase suivante dès l’approbation.', de: 'Nach der Genehmigung geht das Projekt sofort in die nächste Phase.', th: 'โปรเจกต์จะไประยะถัดไปทันทีหลังอนุมัติ', id: 'Proyek akan langsung lanjut ke fase berikutnya setelah disetujui.' },
